<?= view('partials/header',['pageTitle'=>'Payments']) ?><section class="section wrap"><h1>Payments and receipts</h1><p>Records only. This website does not charge cards or automatically verify payments.</p>
<div class="tablewrap"><table><thead><tr><th>Booking</th><th>Amount</th><th>Method</th><th>Status</th><th>Receipt</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td>#<?= esc($p['booking_id']) ?></td><td><?= esc($p['currency']) ?> <?= esc(number_format((float)$p['amount'],2)) ?></td><td><?= esc($p['payment_method'] ?? '—') ?></td><td><?= esc($p['payment_status']) ?></td><td><?= esc($p['receipt_number'] ?? '—') ?></td></tr><?php endforeach; ?><?php if(!$payments): ?><tr><td colspan="5">No payments recorded.</td></tr><?php endif; ?></tbody></table></div>
<?php if(session('role')==='admin'): ?><h2>Record payment (admin only)</h2><form method="post" action="<?= site_url('payments') ?>" class="card form-stack"><?= csrf_field() ?><label>Booking<select name="booking_id" required><?php foreach($bookings as $b): ?><option value="<?= esc($b['booking_id']) ?>">Booking #<?= esc($b['booking_id']) ?></option><?php endforeach; ?></select></label><label>Amount (PHP)<input type="number" min="0" step="0.01" name="amount" required></label><label>Payment method<input name="payment_method" maxlength="60" required></label><label>Status<select name="payment_status"><option>pending</option><option>paid</option><option>failed</option><option>refunded</option></select></label><button type="submit">Save payment record</button></form><?php endif; ?></section><?= view('partials/footer') ?>